import csv

data = []
for row in csv.DictReader(open('inputs/eurostat/eurostat_city_values_sample.csv', 'r', encoding='utf-8')):
    data.append({
        'city_id': row['city_id'],
        'year': row['year'],
        'indicator_id': row['indicator_id'],
    })

# Check for duplicates
seen = set()
unique = []
for row in data:
    key = (row['city_id'], row['year'], row['indicator_id'])
    if key not in seen:
        seen.add(key)
        unique.append(row)

print(f'Unique rows: {len(unique)}')
print(f'Total rows: {len(data)}')

# Check for duplicates
for i, row in enumerate(unique):
    key = (row['city_id'], row['year'], row['indicator_id'])
    if key in seen:
        print(f'Duplicate found: {key}')
